UHierarchicalInstancedStaticMeshComponent* ADukeCityBuilder::Group(const FString& Key, UStaticMesh* Mesh, const FLinearColor& Color, float Roughness, float Emissive, bool bCollide, int32 Kind, float Metallic)
{
	if (TObjectPtr<UHierarchicalInstancedStaticMeshComponent>* Found = Groups.Find(Key)) return *Found;
	UHierarchicalInstancedStaticMeshComponent* G = NewObject<UHierarchicalInstancedStaticMeshComponent>(this, *FString::Printf(TEXT("HISM_%d"), Groups.Num()));
	G->SetupAttachment(RootComponent);
	G->SetStaticMesh(Mesh);
	G->SetMobility(EComponentMobility::Movable);
	if (bCollide) { G->SetCollisionEnabled(ECollisionEnabled::QueryAndPhysics); G->SetCollisionProfileName(TEXT("BlockAll")); }
	else G->SetCollisionEnabled(ECollisionEnabled::NoCollision);
	UMaterialInterface* Base = Kind == 1 ? FacadeBase.Get() : (Kind == 2 ? WaterBase.Get() : ColorBase.Get());
	if (Base)
	{
		UMaterialInstanceDynamic* M = UMaterialInstanceDynamic::Create(Base, this);
		M->SetVectorParameterValue(TEXT("Color"), Color);
		M->SetScalarParameterValue(TEXT("Roughness"), Roughness);
		M->SetScalarParameterValue(TEXT("Metallic"), Metallic);
		M->SetScalarParameterValue(TEXT("Emissive"), Emissive);
		G->SetMaterial(0, M);
		if (Kind == 1 || Emissive > 0.f) NightMats.Add(M);
		if (Kind == 3) WetMats.Add(M);
	}
	G->RegisterComponent();
	Groups.Add(Key, G);
	return G;
}

void ADukeCityBuilder::Add(UHierarchicalInstancedStaticMeshComponent* G, const FVector& L, const FVector& S, float Yaw)
{
	// layout metres (x, z, height) -> Unreal centimetres (X, Y, Z); unit meshes are 1m
	G->AddInstance(FTransform(FRotator(0.f, Yaw, 0.f), FVector(L.X * 100.f, L.Y * 100.f, L.Z * 100.f), S), true);
}

void ADukeCityBuilder::PlaceMesh(const FString& Path, const FVector& L, float Fit, float Yaw, const FLinearColor& Fallback, float FallbackH)
{
	UStaticMesh* SM = Path.IsEmpty() ? nullptr : LoadObject<UStaticMesh>(nullptr, *Path);
	if (!SM)
	{
		Add(Group(TEXT("landmark-fallback"), Cube, Fallback, 0.4f, 0.f, true, 1), FVector(L.X, L.Y, FallbackH * 0.5f), FVector(Fit * 0.7f, Fit * 0.7f, FallbackH));
		return;
	}
	UStaticMeshComponent* C = NewObject<UStaticMeshComponent>(this);
	C->SetupAttachment(RootComponent);
	C->SetStaticMesh(SM);
	C->SetMobility(EComponentMobility::Movable);
	C->SetCollisionProfileName(TEXT("BlockAll"));
	const FVector Ext = SM->GetBounds().BoxExtent * 2.f;
	const float Scale = FMath::Max(Ext.X, Ext.Y) > 1.f ? Fit * 100.f / FMath::Max(Ext.X, Ext.Y) : 1.f;
	const FVector Origin = SM->GetBounds().Origin * Scale;
	C->SetWorldTransform(FTransform(FRotator(0.f, -Yaw, 0.f), FVector(L.X * 100.f, L.Y * 100.f, -(Origin.Z - Ext.Z * Scale * 0.5f)), FVector(Scale)));
	C->RegisterComponent();
}

