void ADukeCityBuilder::SetTime(float Hour, bool bRain)
{
	const float A = (Hour - 6.f) / 12.f * PI;
	const FVector SunDir = FVector(FMath::Cos(A), 0.38f, FMath::Sin(A) * 0.92f).GetSafeNormal(); // towards the sun
	Sun->SetWorldRotation((-SunDir).Rotation());
	Moon->SetWorldRotation(SunDir.Rotation());
	const float El = SunDir.Z;
	const float Day = FMath::SmoothStep(-0.04f, 0.08f, El);
	const float Night = 1.f - FMath::SmoothStep(-0.14f, 0.06f, El);
	Sun->SetIntensity(10.f * Day * (bRain ? 0.35f : 1.f));
	Moon->SetIntensity(0.35f * Night);
	Fog->SetFogDensity(bRain ? 0.05f : 0.012f + Night * 0.006f);
	for (UMaterialInstanceDynamic* M : NightMats) if (M) M->SetScalarParameterValue(TEXT("Night"), Night);
	for (UMaterialInstanceDynamic* M : WetMats) if (M) M->SetScalarParameterValue(TEXT("Roughness"), bRain ? 0.15f : 0.75f);
}
